r() { "$@" > /dev/null 2>&1; local out=$(echo "$@" | sed -n 's/.*--out \([^ ]*\).*/\1/p'); echo "### $*"; sed -n '/^Start time/,/^End time/p' $out.log | grep -vE "^(Start|End) time|RAM detected|Random number seed|^Using [0-9]+ thread|^$|Ambiguous sex IDs|Ignoring phenotypes of missing-sex|phenotypes to be ignored|het. haploid|treat these as missing|these as missing|Calculating allele freq|founders and .* nonfounders present|loaded from .bim|loaded from .fam|phenotype values loaded"; }
